// Transcript rows (turnStatusRows): the 2.42304.0 status rows generated by scripts/extract-transcript-rows.mjs, mounted
// by src/source-transcript-rows.jsx under the transcript root's scope. SSR in middleware mode only (hmr / ws off).
import test, { before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { createServer } from 'vite';
import react from '@vitejs/plugin-react';
import { extractTranscriptRows } from '../scripts/extract-transcript-rows.mjs';

const app = path.resolve(import.meta.dirname, '..');
const dir = path.join(app, 'src/generated/transcript-rows');
const manifest = JSON.parse(fs.readFileSync(path.join(dir, 'manifest.json'), 'utf8'));
let server, Rows, Session, Group, Model, Growth;
before(async () => {
  server = await createServer({ configFile: false, root: app, plugins: [react()], server: { middlewareMode: true, hmr: false, ws: false, watch: null },
    appType: 'custom', logLevel: 'error' });
  Rows = await server.ssrLoadModule('/src/source-transcript-rows.jsx');
  Session = await server.ssrLoadModule('/src/source-session.jsx');
  Group = await server.ssrLoadModule('/src/source-tool-group.jsx');
  Model = await server.ssrLoadModule('/src/transcript-rows-model.mjs');
  Growth = await server.ssrLoadModule('/src/host-growthbook.mjs');
});
after(() => server?.close());
const h = React.createElement;
const inScope = (child, scope = {}) => renderToStaticMarkup(h(Rows.TranscriptRowsScope, { sessionKey: 'code:s', ...scope }, child));

test('generator --check, linked to the working line (one TurnStatus, one gate, one mark)', async () => {
  await extractTranscriptRows({ check: true });
  // 2026-10-18: the session rail is linked too (shared-25 $U/YU, shared-78 YD/sN, shared-130 Y were sliced in both areas).
  // 2026-10-18 (tool results): r3b-transcript's session file contexts and files-changes' gone check / session id context
  // are linked module by module (the file link reads the same contexts as the Turn edits card and the Files pane).
  assert.deepEqual(manifest.linkedAreas, ['working-line', 'session-rail', { area: 'r3b-transcript', modules: ['session-file-access.mjs'] },
    { area: 'files-changes', modules: ['file-gone-check.mjs', 'session-context.mjs'] }]);
  assert.ok(fs.existsSync(path.join(app, 'scripts/verify-gen-transcript-rows.mjs')));
  const group = fs.readFileSync(path.join(dir, 'group-status.mjs'), 'utf8');
  assert.match(group, /import \{ TurnStatus as up \} from "\.\.\/working-line\/turn-status\.mjs";/);
  for (const feature of ['m = p ? "blocked" : f ? "busy" : n,', 'leading: o && !v ? x : null,', 'XAe as GroupStatusRow', 'ZAe as RunningToolRow'])
    assert.ok(group.includes(feature), feature);
  const mark = fs.readFileSync(path.join(dir, 'turn-mark.mjs'), 'utf8');
  assert.match(mark, /from "\.\.\/working-line\/morph\.mjs";/, 'the broker context is the working line\'s');
  assert.ok(mark.includes('"data-turn-mark-outlet": "",'));
  // No binding is sliced in both areas.
  const wl = JSON.parse(fs.readFileSync(path.join(app, 'src/generated/working-line/manifest.json'), 'utf8'));
  const held = new Set(wl.modules.flatMap(m => m.bindings.map(b => `${m.source}#${b.name}`)));
  for (const m of manifest.modules) for (const b of m.bindings) assert.ok(!held.has(`${m.source}#${b.name}`), `${m.source}#${b.name}`);
});

test('one host GrowthBook table answers every area', () => {
  assert.equal(Growth.hostGrowthBookFlag('__gb__2846116625'), true);
  assert.equal(Growth.hostGrowthBookFlag('__gb__507049721'), true);
  assert.equal(Growth.hostGrowthBookFlag('__gb__3525173228'), true);
  assert.equal(Growth.hostGrowthBookFlag('__gb__1785002156'), false);
  for (const file of ['source-working-line-adapters.jsx', 'source-r3b-transcript-adapters.jsx', 'source-turn-box-adapters.jsx', 'source-proposal-group-adapters.jsx',
    'source-mcp-app-card-adapters.jsx', 'source-mcp-app-host-adapters.jsx', 'source-session-rail-sections-adapters.jsx'])
    assert.match(fs.readFileSync(path.join(app, 'src', file), 'utf8'), /from "\.\/host-growthbook\.mjs";/, file);
});

test('a tool row in the transcript scope is the CDS TurnStatus.Step; outside it the classic row', () => {
  const item = { id: 'c1', turnId: 't', type: 'commandExecution', command: 'ls -la', status: 'completed', aggregatedOutput: 'ok', exitCode: 0 };
  const row = inScope(h(Session.SourceMessage, { item, sessionKey: 's' }));
  assert.match(row, /data-cds="TurnStatusStep"/);
  assert.match(row, /data-transcript-item-id="c1"/);
  assert.doesNotMatch(row, /source-step-trigger/);
  const classic = renderToStaticMarkup(h(Session.SourceMessage, { item, sessionKey: 's' }));
  assert.match(classic, /source-step-trigger/);
});

test('a running tool row holds the turn\'s mark (ZAe) while the turn is live', () => {
  const item = { id: 'c2', turnId: 't', type: 'commandExecution', command: 'sleep 5', status: 'inProgress' };
  const html = inScope(h(Session.SourceMessage, { item, sessionKey: 's' }), { turnId: 't', items: [item], itemPhases: {}, responding: true,
    turnStats: { turnId: 't', startedAt: Date.now() / 1000 - 30 } });
  assert.match(html, /data-transcript-item-id="c2"/);
  assert.match(html, /data-state="busy"/);
});

test('reasoning is HZ, the open "Thought process" step', () => {
  const item = { id: 'r1', turnId: 't', type: 'reasoning', summary: ['Looking at the files'] };
  const html = inScope(h(Session.SourceMessage, { item, sessionKey: 's', transcriptView: 'thinking' }));
  if (html === '') return; // the view hides thinking: nothing to compare
  assert.match(html, /Thought process/);
  assert.match(html, /data-cds="TurnStatusStep"/);
});

test('a tool group is v2e\'s XAe: TurnStatus over the members, phrases and the diff counts when done', () => {
  const tools = [
    { id: 'f1', turnId: 't', type: 'fileChange', status: 'completed', changes: [{ path: 'a.js', kind: { type: 'update' }, diff: '@@ -1 +1,2 @@\n-a\n+b\n+c' }] },
    { id: 'c3', turnId: 't', type: 'commandExecution', command: 'npm test', status: 'completed', aggregatedOutput: '' },
  ];
  const item = { id: 'g1', type: 'fileToolGroup', toolGroup: tools };
  const html = inScope(h(Group.SourceToolGroup, { item, sessionKey: 's', pendingApprovalItemIds: new Set(), transcriptView: 'normal',
    renderItem: member => h(Session.SourceMessage, { item: member, sessionKey: 's', inToolGroup: true }) }));
  assert.match(html, /data-tool-group="g1"/);
  assert.match(html, /data-cds="TurnStatus" data-state="done"/);
  assert.match(html, /data-cds-phrases=/);
  assert.match(html, /data-cds="DiffIndicator"/);
});

test('the transcript tail puts the mark outlet in the working line\'s grid cell; the root carries the scope', () => {
  const html = inScope(h(Rows.TranscriptTail, null, h('div', { id: 'line' })));
  assert.match(html, /^<div class="grid grid-cols-\[minmax\(0,1fr\)\][^"]*\[&amp;&gt;\[data-turn-mark-outlet\]\]:\[grid-area:1\/1\]"><div data-turn-mark-outlet="" class="empty:hidden" aria-hidden="true"><\/div><div id="line"><\/div><\/div>$/);
  const transcript = fs.readFileSync(path.join(app, 'src/source-transcript.jsx'), 'utf8');
  assert.match(transcript, /<TranscriptRowsScope sessionKey=\{sessionKey\}/);
  const main = fs.readFileSync(path.join(app, 'src/main.jsx'), 'utf8');
  assert.equal(main.split('turnScope={current ? { turnId: state.active[current], turnStats: state.turnStats?.[current], items: state.items[current], itemPhases: state.itemPhases?.[current] } : null}').length - 1, 1);
});

test('model: SDK tool names for the mark\'s activity, the live scope, the running candidate', () => {
  assert.deepEqual(Model.sdkToolOf({ type: 'commandExecution', command: 'ls' }), { name: 'Bash', input: { command: 'ls' } });
  assert.equal(Model.sdkToolOf({ type: 'agentMessage' }), null);
  const items = [{ id: 'a', turnId: 't', type: 'commandExecution', status: 'inProgress' }, { id: 'b', turnId: 't', type: 'agentMessage' }];
  const scope = Model.transcriptLiveScope({ sessionKey: 's', turnId: 't', items, responding: true, turnStats: { turnId: 't', startedAt: 10 }, awaiting: true });
  assert.deepEqual([...scope.liveRunningToolIds], ['a']);
  assert.equal(scope.turnStartedAt, 10000); assert.equal(scope.awaiting, true); assert.equal(scope.lastTool.name, 'Bash');
  assert.deepEqual(Model.runningCandidate(items[0]), { key: 'a', name: 'Bash', input: { command: '' }, wireRunning: true, toolIds: ['a'], runningIds: ['a'] });
  assert.equal(Model.stepState('unknown'), 'done');
});

// The tool rows themselves (user ruling: the transcript follows the desktop): c96d752d0 n0 (v2e) / e0 / Uz (JIe) / HZ over
// the SDK tool calls the host converts its engine items to (transcript-sdk-tools.mjs), mounted by
// source-transcript-tool-rows.jsx; the host's bodies, cards and file opener through the adapters.
const strip = html => html.replace(/ class="[^"]*"/g, '');
const cmd = { id: 'c1', turnId: 't', type: 'commandExecution', command: 'npm test', description: 'Run the tests', status: 'completed', aggregatedOutput: 'PASS', exitCode: 0 };
const edit = { id: 'f1', turnId: 't', type: 'fileChange', status: 'completed', changes: [{ path: '/w/src/a.js', kind: { type: 'update' }, diff: '@@ -1,2 +1,3 @@\n a\n-b\n+c\n+d\n' }] };
const read = { id: 'r1', turnId: 't', type: 'commandExecution', command: 'cat a.js', status: 'completed', aggregatedOutput: '1\tconst a = 1', commandActions: [{ type: 'read', path: '/w/src/a.js', name: 'a.js' }] };

test('generator: the tool rows are originals, their boundary is pinned adapters', () => {
  const group = fs.readFileSync(path.join(dir, 'group-status.mjs'), 'utf8');
  for (const feature of ['n0 as ToolGroupRows', 'e0 as ToolGroupMember', 'Uz as ToolRow', 'HZ as ThoughtProcessStep', 'function JIe(', 'function v2e(', 'function UIe(',
    '(e) => e.epitaxyEngineToolRow,', 'defaultMessage: "Needs your input",'])
    assert.ok(group.includes(feature), feature);
  const summary = fs.readFileSync(path.join(dir, 'rows-c52b02f3f-DUwt0Dsx.mjs'), 'utf8');
  for (const feature of ['case "Bash":', 'defaultMessage: "Ran",', 'defaultMessage: "Searched web",', 'defaultMessage: "Ran agent",']) assert.ok(summary.includes(feature), feature);
  const c96 = manifest.modules.find(m => m.target === 'group-status.mjs');
  const adapted = new Set(c96.imports.filter(i => i.kind === 'adapter').map(i => i.name));
  for (const name of ['useEngineSurface', 'McpAppToolCard', 'PeerSendCard', 'CoordinatorMessageCard', 'EnvironmentSetupSteps', 'LiveOutputButton'])
    assert.ok(adapted.has(name), name);
  // 2026-10-18: the result body (KIe → GIe → cb6930dae Tu) and the file link (c856385e2 In) are originals now.
  for (const name of ['HostToolResult', 'FileLink']) assert.ok(!adapted.has(name), name);
  // No local adapter shadows a declaration that is also sliced.
  const sliced = new Set(c96.bindings.map(b => b.name));
  for (const local of ['fM', 'xM', '_M', 'oQ', 'Q$', 'NW', 'VX']) assert.ok(!sliced.has(local), local);
  for (const local of ['KIe', 'GIe', 'zz']) assert.ok(sliced.has(local), local);
});

test('a standalone tool row reads its label from c52b02f3f fn by SDK tool name', () => {
  const row = item => strip(inScope(h(Session.SourceMessage, { item, sessionKey: 's' })));
  assert.match(row(cmd), /data-transcript-item-id="c1"[\s\S]*data-cds="TurnStatusStep" data-state="done"[\s\S]*Ran the tests/);
  assert.match(row(read), /<span dir="auto">Read<\/span>[\s\S]*<bdi>a\.js<\/bdi>/);
  assert.match(row(edit), /<span dir="auto">Edited<\/span>[\s\S]*data-cds="DiffIndicator"[\s\S]*2 added, 1 removed/);
  assert.match(row({ id: 'w', turnId: 't', type: 'webSearch', query: 'react 19', status: 'completed', action: { type: 'search', query: 'react 19' } }), /Searched web react 19/);
  assert.match(row({ id: 'u', turnId: 't', type: 'webSearch', status: 'completed', action: { type: 'openPage', url: 'https://example.com/x' } }), /Fetched/);
  assert.match(row({ id: 'k', turnId: 't', type: 'dynamicToolCall', namespace: null, tool: 'skill', arguments: { name: 'pdf' }, status: 'completed' }), /Ran skill[\s\S]*\/pdf/);
  assert.match(row({ id: 'x', turnId: 't', type: 'commandExecution', command: 'false', status: 'failed', aggregatedOutput: 'boom' }), /data-state="failed"/);
  // The gate off: the host's classic row.
  assert.match(renderToStaticMarkup(h(Session.SourceMessage, { item: cmd, sessionKey: 's' })), /source-step-trigger/);
});

test('a tool group is the original v2e: summary, diff counts, members as original rows over the original bodies', () => {
  const item = { ...read, type: 'fileToolGroup', toolGroup: [read, edit, cmd] };
  const closed = strip(inScope(h(Session.SourceMessage, { item, sessionKey: 's' })));
  assert.match(closed, /^<div data-tool-group="r1" data-group-state="done" data-transcript-item-id="r1">/);
  assert.match(closed, /data-cds="TurnStatus" data-state="done"/);
  assert.match(closed, /Read and edited a\.js, ran a command/);
  assert.match(closed, /data-cds="DiffIndicator"/);
  const open = inScope(h(Session.SourceMessage, { item, sessionKey: 's', transcriptView: 'verbose' }));
  // cb6930dae Tu: the Read preview and the Edit diff are pierre's File / FileDiff (diffs-container), the command is Cu
  // (inside a group's card: the command line, then the output).
  assert.equal(open.match(/<diffs-container>/g)?.length, 3, 'Read preview, Edit diff, the command line');
  assert.match(open, /aria-label="Tool output"[^>]*>PASS</, 'the command body (Cu in the card: the command line, then its output)');
  assert.doesNotMatch(open, /class="sft-(read|diff)/, 'no host body');
  assert.equal(open.match(/data-cds="TurnStatusStep"/g).length, 3);
});

